const end = Date.parse('2026-10-21T14:45:40Z');
const got = [];
let misses = 0;
while (Date.now() < end && misses < 3) {
  const t = sdk.findNearbyNpc(/^(ghost|skeleton|zombie|hobgoblin|frog|lizard|goblin guard|moss giant|hill giant|wolf|jackal|giant bat|scorpion|guard|farmer|bandit|dark wizard)$/i) || null;
  if (!t) { misses++; await new Promise(r => setTimeout(r, 800)); continue; }
  const r = await bot.attack(t, 15000);
  got.push(`${t.name}:${r.success ? 'ok' : r.reason}`);
  if (!r.success) misses++;
  await new Promise(r => setTimeout(r, 800));
}
return { got: got.slice(-6), now: new Date().toISOString() };
